    await ctx.commands.execute(agent, '/denied', new AbortController().signal)
    expect(lifecycleOf(agent)).toMatchObject([
      { type: 'command/run', data: { name: 'denied' } },
      { type: 'command/done', data: { kind: 'error', text: 'not now' } },
